options.onMounted:
const _this = this
async function getOptions () {
  const data = await $api.get('/docpalType/settings/metadata/GlobalFile').then(res => res.data.data)
  const options = data.keywords.reduce((prev,item) => {
    if (item.name) prev.push({
      label: item.name,
      value: item.name
    })
    return prev
  }, [])
  _this.loadOptions(options)
}
getOptions()

